    "title": "The Art of Illustration",
    "deck": "C. H. Spurgeon — Baptist preacher C. H. Spurgeon teaches how to use illustrations and examples for effective preaching.",
    "source": "Standard Ebooks",
    "sourceId": "standard-ebooks",
    "sourceUrl": "https://standardebooks.org/ebooks/c-h-spurgeon/the-art-of-illustration",
